const fresh=()=>({hatched:false,food:65,mood:65,energy:75,care:0});
export function mountPet(root,beep){
 let pet;try{pet={...fresh(),...JSON.parse(localStorage.getItem('gyu_mini_pet_v1'))}}catch{pet=fresh()}
 let busy=false,timer,message=pet.hatched?'다시 만나서 반가워!':'알을 눌러 작은 친구를 만나세요.';
 const save=()=>{try{localStorage.setItem('gyu_mini_pet_v1',JSON.stringify(pet))}catch{}};
 root.insertAdjacentHTML('beforeend',`<div class="pet-game"><div class="pet-caption">LITTLE FRIEND · 짧은 돌봄 체험</div><div class="pet-room"><div class="pet-window">☀</div><div class="pet-rug"></div><button class="pet-creature" aria-label="알 부화시키기"><span class="pet-egg">◒</span><img src="character.png" alt="돌보는 작은 도트 친구" hidden></button><span class="pet-effect" aria-hidden="true"></span></div><p class="pet-message" role="status"></p><div class="pet-meters">${[['food','배부름'],['mood','기분'],['energy','에너지']].map(([k,label])=>`<label>${label}<progress data-meter="${k}" max="100" value="65"></progress><span data-value="${k}"></span></label>`).join('')}</div><div class="pet-actions"><button data-care="feed">먹이 주기</button><button data-care="play">놀아주기</button><button data-care="rest">쉬기</button></div><p class="pet-growth"></p><p class="pet-note">이 브라우저에 자동 저장돼요. 잠시 자리를 비워도 친구는 기다려요.</p><button class="pet-reset">새 친구 만나기</button></div>`);
 const q=s=>root.querySelector(s),creature=q('.pet-creature');
 function render(){q('.pet-egg').hidden=pet.hatched;q('.pet-creature img').hidden=!pet.hatched;creature.setAttribute('aria-label',pet.hatched?'친구 쓰다듬기':'알 부화시키기');creature.classList.toggle('grown',pet.care>=6);q('.pet-message').textContent=message;q('.pet-growth').textContent=pet.hatched?pet.care>=6?'✦ 조금 더 자랐어요! 계속 함께 놀아요.':`성장까지 ${Math.max(0,6-pet.care)}번의 돌봄`:'알 속에서 꼬물꼬물…';for(const k of ['food','mood','energy']){q(`[data-meter="${k}"]`).value=pet[k];q(`[data-value="${k}"]`).textContent=Math.round(pet[k]);}root.querySelectorAll('[data-care]').forEach(b=>b.disabled=!pet.hatched||busy);save()}
 function animate(kind,effect){creature.classList.remove('pet-feed','pet-play','pet-rest');void creature.offsetWidth;creature.classList.add(`pet-${kind}`);q('.pet-effect').textContent=effect;busy=true;render();clearTimeout(timer);timer=setTimeout(()=>{busy=false;creature.classList.remove(`pet-${kind}`);q('.pet-effect').textContent='';render()},1000)}
 creature.onclick=()=>{if(busy)return;if(!pet.hatched){pet.hatched=true;message='안녕! 나를 돌봐 줄래?';beep(880,.12);animate('play','♡')}else{message='쓰다듬어 줘서 좋아!';beep(660,.06);animate('play','♡')}render()};
 root.querySelectorAll('[data-care]').forEach(b=>b.onclick=()=>{if(busy||!pet.hatched)return;const action=b.dataset.care;if(action==='play'&&pet.energy<20){message='조금 졸려… 먼저 쉬고 싶어.';render();return}if(action==='feed'){pet.food=Math.min(100,pet.food+22);message='냠냠! 맛있다.';animate('feed','✦')}if(action==='play'){pet.mood=Math.min(100,pet.mood+25);pet.energy=Math.max(15,pet.energy-12);pet.food=Math.max(15,pet.food-7);message='같이 노니까 신난다!';animate('play','♡')}if(action==='rest'){pet.energy=Math.min(100,pet.energy+28);message='잠깐 쉬고 다시 놀자.';animate('rest','Z z')}pet.care++;if(pet.care===6)message='쑥! 너와 함께 조금 더 자랐어!';beep(action==='rest'?330:770,.08);render()});
 q('.pet-reset').onclick=()=>{if(!confirm('현재 친구의 돌봄 기록을 초기화하고 새 알을 만날까요?'))return;clearTimeout(timer);busy=false;pet=fresh();message='새로운 친구가 기다리고 있어요.';q('.pet-effect').textContent='';creature.classList.remove('pet-feed','pet-play','pet-rest');render()};
 const decay=setInterval(()=>{if(!pet.hatched||document.hidden||busy)return;for(const k of ['food','mood','energy'])pet[k]=Math.max(15,pet[k]-1);render()},15000);render();
 return ()=>{clearInterval(decay);clearTimeout(timer);save()};
}
